function criarOrcamento({ buscarPreco, registrar }) {
  return function orcar(id, quantidade) {
    const preco = buscarPreco(id);
    if (!Number.isInteger(preco) || preco < 0) throw new Error("preço indisponível");
    if (!Number.isInteger(quantidade) || quantidade < 0) throw new Error("quantidade inválida");
    const total = preco * quantidade;
    registrar({ id, total });
    return total;
  };
}
