import { createServer } from "node:http";
import assert from "node:assert/strict";
const ordens = [];
const servidor = createServer(async (req, res) => {
  const enviar = (status, corpo) => { res.writeHead(status, { "content-type": "application/json; charset=utf-8" }); res.end(JSON.stringify(corpo)); };
  try {
    if (req.method !== "POST" || req.url !== "/ordens") { req.resume(); enviar(404, { erro: "rota ausente" }); return; }
    let tamanho = 0; const partes = [];
    for await (const parte of req.iterator({ destroyOnReturn: false })) {
      tamanho += parte.length;
      if (tamanho > 1024) throw new RangeError("corpo grande");
      partes.push(parte);
    }
    const dado = JSON.parse(Buffer.concat(partes).toString("utf8"));
    if (!dado || typeof dado.id !== "string" || !/^OS-\d+$/.test(dado.id)) throw new TypeError("ID inválido");
    const ordem = { id: dado.id, status: "aberta" }; ordens.push(ordem); enviar(201, ordem);
  } catch (erro) {
    req.resume(); // Descarta o restante sem destruir o socket antes da resposta.
    enviar(erro instanceof RangeError ? 413 : 400, { erro: erro.message });
  }
});
await new Promise(resolve => servidor.listen(0, "127.0.0.1", resolve));
const base = `http://127.0.0.1:${servidor.address().port}/ordens`;
try {
  const resposta = await fetch(base, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: "OS-1" }), signal: AbortSignal.timeout(2000) });
  console.log(resposta.status, (await resposta.json()).status);
  const grande = await fetch(base, { method: "POST", body: "x".repeat(1200), signal: AbortSignal.timeout(2000) });
  assert.equal(grande.status, 413); await grande.text(); console.log(grande.status);
  assert.equal(ordens.length, 1); console.log(ordens.length);
} finally { servidor.closeAllConnections(); await new Promise(resolve => servidor.close(resolve)); }

