import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";
if (isMainThread) {
  const worker = new Worker(new URL(import.meta.url), { workerData: 10000 });
  const total = await new Promise((resolve, reject) => {
    let resultado;
    worker.once("message", valor => { resultado = valor; });
    worker.once("error", reject);
    worker.once("exit", codigo => { if (codigo !== 0) reject(new Error(`worker terminou com ${codigo}`)); else resolve(resultado); });
  });
  console.log(total);
} else {
  let total = 0;
  for (let i = 1; i <= workerData; i += 1) total += i;
  parentPort.postMessage(total);
}

