import assert from "node:assert/strict";
const estado = { saldo: 5, ordens: new Map([["OS-1", { status: "aberta", quantidade: 2 }]]), pedidos: new Map() };
function confirmar(chave, id) {
  if (typeof chave !== "string" || chave.trim() === "" || typeof id !== "string" || id.trim() === "") throw new TypeError("chave e ID obrigatórios");
  const anterior = estado.pedidos.get(chave);
  if (anterior) { if (anterior.id !== id) throw new Error("chave reutilizada"); return anterior; }
  const ordem = estado.ordens.get(id);
  if (!ordem) throw new Error("ordem ausente");
  if (ordem.status === "aberta") {
    if (ordem.quantidade > estado.saldo) throw new Error("estoque insuficiente");
    estado.saldo -= ordem.quantidade; ordem.status = "confirmada";
  }
  const resposta = { id, status: ordem.status, saldo: estado.saldo };
  estado.pedidos.set(chave, resposta); return resposta;
}
confirmar("pedido-1", "OS-1");
confirmar("pedido-1", "OS-1");
confirmar("pedido-2", "OS-1");
assert.equal(estado.saldo, 3);
