const ordens = new Map([["OS-1", { id: "OS-1", status: "aberta", quantidade: 2 }]]);
let saldo = 5;
function confirmar(id) {
  const ordem = ordens.get(id);
  if (!ordem) throw new Error("ordem ausente");
  if (ordem.status === "aberta") {
    if (ordem.quantidade > saldo) throw new Error("estoque insuficiente");
    saldo -= ordem.quantidade; ordem.status = "confirmada";
  }
  return { id: ordem.id, status: ordem.status, saldo };
}
const pagina = `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Oficina JavaScript</title><h1>Ordens locais</h1><form id="form"><label for="id">ID da ordem</label><input id="id" value="OS-1" required><button>Confirmar</button></form><p id="estado" role="status"></p><script>
document.querySelector("#form").addEventListener("submit", async function(event) {
  event.preventDefault(); const estado = document.querySelector("#estado");
  try { const resposta = await fetch("/api/confirmar", {method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({id:document.querySelector("#id").value.trim()})}); const dado = await resposta.json(); if(!resposta.ok)throw new Error(dado.erro || "falha"); estado.textContent = dado.id + " " + dado.status + "; saldo " + dado.saldo; }
  catch(erro) { estado.textContent = erro.message; }
});
</script></html>`;
const servidor = createServer(async (req, res) => {
  const json = (status, dado) => { res.writeHead(status, { "content-type": "application/json; charset=utf-8" }); res.end(JSON.stringify(dado)); };
  try {
    if (req.method === "GET" && req.url === "/") { res.writeHead(200, { "content-type": "text/html; charset=utf-8" }); res.end(pagina); return; }
    if (req.method !== "POST" || req.url !== "/api/confirmar") { json(404, { erro: "rota ausente" }); return; }
    let bytes = 0; const partes = [];
    for await (const parte of req.iterator({ destroyOnReturn: false })) { bytes += parte.length; if(bytes > 2048)throw new RangeError("corpo grande"); partes.push(parte); }
    const dado = JSON.parse(Buffer.concat(partes).toString("utf8"));
    if (!dado || typeof dado.id !== "string" || !/^OS-\d+$/.test(dado.id)) throw new Error("ID inválido");
    json(200, confirmar(dado.id));
  } catch (erro) { req.resume(); json(erro instanceof RangeError ? 413 : 400, { erro: erro.message }); }
});
const manual = process.argv.includes("--servir");
await new Promise(resolve => servidor.listen(manual ? 8787 : 0, "127.0.0.1", resolve));
